#!/usr/bin/env node
/**
 * Generate the website models catalog, auto-synced from the bundled model
 * catalog that veyyon ships.
 *
 *   node apps/site/tools/gen-models.mjs
 *
 * The single source of truth for every provider and model veyyon supports is
 * `packages/catalog/src/models.json`, regenerated by `bun run gen:models` from
 * upstream provider endpoints. This tool reads it, pairs each provider with the
 * human-readable label and default model declared in `descriptors.ts`, and
 * writes a compact `apps/site/models-data.json` that the models page fetches and
 * renders client-side.
 *
 * The page is "automatically refreshed" two ways: `bun run site:build` regener
 * ates this file from the committed catalog, and the live page fetches it from
 * jsDelivr's `@main` mirror of this repo, so a catalog regen committed to `main`
 * shows up on veyyon.dev within jsDelivr's cache window with no site deploy.
 *
 * `models.json` is generated, never hand-edited (see AGENTS.md). This tool only
 * reads it. Labels that `descriptors.ts` does not publish (`catalogDiscovery.
 * label` is optional) fall back to a curated override map, then to a title-cased
 * provider id, so a new provider always gets a readable label.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");
const CATALOG = join(REPO_ROOT, "packages", "catalog", "src", "models.json");
const DESCRIPTORS = join(REPO_ROOT, "packages", "catalog", "src", "provider-models", "descriptors.ts");
const OUT = join(HERE, "..", "models-data.json");

/**
 * Providers whose `descriptors.ts` entry carries no `catalogDiscovery.label`
 * (or no entry at all). These are well-known brands whose title-cased id reads
 * wrong ("Openai", "Xai", "Github Copilot"). A new provider not listed here
 * falls through to {@link titleCase}, so this map never blocks a label.
 */
const LABEL_OVERRIDES = {
	"amazon-bedrock": "Amazon Bedrock",
	azure: "Azure",
	firepass: "Firepass",
	"github-copilot": "GitHub Copilot",
	"gitlab-duo": "GitLab Duo",
	"gitlab-duo-agent": "GitLab Duo Agent",
	google: "Google",
	"google-antigravity": "Google Antigravity",
	"google-gemini-cli": "Google Gemini CLI",
	"google-vertex": "Google Vertex",
	groq: "Groq",
	minimax: "MiniMax",
	"minimax-cn": "MiniMax (CN)",
	"minimax-code": "MiniMax Code",
	"minimax-code-cn": "MiniMax Code (CN)",
	mistral: "Mistral",
	openai: "OpenAI",
	"openai-codex": "OpenAI Codex",
	opencode: "OpenCode",
	"opencode-go": "OpenCode Go",
	"opencode-zen": "OpenCode Zen",
	xai: "xAI",
	"xiaomi-token-plan-ams": "Xiaomi (AMS)",
	"xiaomi-token-plan-cn": "Xiaomi (CN)",
	"xiaomi-token-plan-sgp": "Xiaomi (SGP)",
};

/** Title-case a provider id: `alibaba-coding-plan` → `Alibaba Coding Plan`. */
export function titleCase(id) {
	return id.split(/[-_]/).map(w => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(" ");
}

/** Resolve a provider's display label: override map → descriptor label → title-case. */
export function resolveLabel(id, descriptorLabel) {
	return LABEL_OVERRIDES[id] ?? descriptorLabel ?? titleCase(id);
}

/**
 * Parse `descriptors.ts` into `{ id → { label, defaultModel } }`. The file is a
 * single `CATALOG_PROVIDERS` array of flat entries; splitting on the entry
 * boundary (`},\n\t{`) keeps each chunk to one provider so the label regex
 * cannot bleed across entries the way a greedy span would.
 *
 * Only providers with a `CATALOG_PROVIDERS` entry have runtime support: env-var
 * resolution, a model-manager factory (or a special OAuth builder), and a
 * default model. `models.json` can contain providers that lack an entry —
 * `minimax-cn` has a models.dev descriptor but no catalog entry, and `opencode`
 * is a legacy id for `opencode-zen` carried forward from a previous snapshot —
 * so the descriptor id set is the filter that keeps non-functional providers off
 * the page.
 */
export function parseDescriptors(src) {
	const body = src.slice(src.indexOf("CATALOG_PROVIDERS = ["), src.indexOf("] as const"));
	const chunks = body.split("},\n\t{");
	const out = {};
	for (const chunk of chunks) {
		const idM = chunk.match(/id:\s*"([^"]+)"/);
		if (!idM) continue;
		const labelM = chunk.match(/label:\s*"([^"]+)"/);
		const defM = chunk.match(/defaultModel:\s*"([^"]+)"/);
		out[idM[1]] = { label: labelM?.[1] ?? null, defaultModel: defM?.[1] ?? null };
	}
	return out;
}
/**
 * Local / self-hosted providers. These have `CATALOG_PROVIDERS` entries (so they
 * are supported) but are never bundled in `models.json`: their model list is
 * whatever is running on the user's machine, discovered at runtime. The page
 * lists them separately so a reader sees the full supported-provider surface.
 */
const LOCAL_PROVIDERS = [
	{ id: "ollama", label: "Ollama", envVar: "OLLAMA_API_KEY" },
	{ id: "lm-studio", label: "LM Studio", envVar: "LM_STUDIO_API_KEY" },
	{ id: "vllm", label: "vLLM", envVar: "VLLM_API_KEY" },
	{ id: "litellm", label: "LiteLLM", envVar: "LITELLM_API_KEY" },
];

/**
 * Build the compact catalog payload from the raw `models.json` and the parsed
 * descriptor metadata. Only providers with a `CATALOG_PROVIDERS` entry are
 * included — that is the set veyyon can authenticate and stream to. Local
 * providers (Ollama, vLLM, LM Studio, LiteLLM) are appended with no model list;
 * their models are discovered at runtime from the user's server.
 *
 * Null context windows and output caps are omitted (the page treats absence as
 * "unpublished"); costs are kept as USD per million tokens, 0 meaning free.
 */
export function buildPayload(catalog, descriptors) {
	const providers = [];
	let modelCount = 0;
	for (const id of Object.keys(catalog).sort()) {
		// Skip providers without a CATALOG_PROVIDERS entry: they have no
		// runtime auth path (minimax-cn) or are legacy ids (opencode).
		if (!(id in descriptors)) continue;
		const entries = catalog[id];
		const ids = Object.keys(entries);
		modelCount += ids.length;
		const meta = descriptors[id] ?? {};
		const models = ids
			.map(mid => entries[mid])
			.sort((a, b) => (a.name || a.id).localeCompare(b.name || b.id) || a.id.localeCompare(b.id))
			.map(e => {
				const m = { id: e.id, name: e.name || e.id };
				if (e.reasoning) m.r = true;
				if (Array.isArray(e.input) && e.input.length) m.i = e.input;
				if (e.contextWindow != null) m.ctx = e.contextWindow;
				if (e.maxTokens != null) m.max = e.maxTokens;
				const c = e.cost ?? {};
				m.ci = c.input ?? 0;
				m.co = c.output ?? 0;
				return m;
			});
		providers.push({
			id,
			label: resolveLabel(id, meta.label),
			defaultModel: meta.defaultModel ?? ids[0] ?? null,
			count: ids.length,
			models,
		});
	}
	// Local providers: supported but discovered at runtime, no bundled models.
	for (const lp of LOCAL_PROVIDERS) {
		if (lp.id in descriptors) {
			providers.push({ ...lp, defaultModel: descriptors[lp.id].defaultModel ?? null, count: 0, models: [], local: true });
		}
	}
	providers.sort((a, b) => a.label.localeCompare(b.label));
	return {
		generated: new Date().toISOString().slice(0, 10),
		providerCount: providers.length,
		modelCount,
		providers,
	};
}

async function main() {
	const catalog = JSON.parse(readFileSync(CATALOG, "utf8"));
	const descriptors = parseDescriptors(readFileSync(DESCRIPTORS, "utf8"));
	const payload = buildPayload(catalog, descriptors);
	writeFileSync(OUT, JSON.stringify(payload) + "\n");
	console.log(`models: ${payload.providerCount} providers, ${payload.modelCount} models → ${OUT}`);
}

// Run only when invoked directly (not when imported by a test).
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
	await main();
}
